script.lang:
DROP VIEW IF EXISTS v_ni_indicator_funding CASCADE; create view v_ni_indicator_funding AS
select DISTINCT ic.activity_id as amp_activity_id, iv.value, iv.value_type, iv.value_date as value_date, ic.indicator_id as me_indicator_id, t.amp_theme_id AS program_id, NULL::integer AS category_value_id, ind.output_id, ind.outcome_id from amp_indicator i join amp_indicator_connection ic ON i.indicator_id = ic.indicator_id and ic.sub_clazz = 'a' join amp_indicator_values iv ON ic.id = iv.ind_connect_id join amp_activity_version a ON ic.activity_id = a.amp_activity_id left JOIN amp_indicator ind ON ind.indicator_id = ic.indicator_id LEFT JOIN amp_theme t ON ind.program_id = t.amp_theme_id LEFT JOIN amp_theme t2 ON t.parent_theme_id = t2.amp_theme_id
UNION ALL
/* indicator's base/target values from admin section (basic, not disaggregated) */ select DISTINCT ic.activity_id as amp_activity_id, aigv.original_value, aigv.type as value_type, aigv.original_value_date as value_date, ic.indicator_id as me_indicator_id, t.amp_theme_id AS program_id, NULL::integer AS category_value_id, ind.output_id, ind.outcome_id from amp_indicator i join amp_indicator_connection ic ON i.indicator_id = ic.indicator_id and ic.sub_clazz = 'a' join amp_indicator_global_value aigv ON ic.indicator_id = aigv.indicator_id left JOIN amp_indicator ind ON ind.indicator_id = ic.indicator_id LEFT JOIN amp_theme t ON ind.program_id = t.amp_theme_id LEFT JOIN amp_theme t2 ON t.parent_theme_id = t2.amp_theme_id
UNION ALL
/* indicator's values from admin section (disaggregated) - base values */ select DISTINCT con.activity_id as amp_activity_id, aigv.original_value AS value, /*aigv.type as value_type,*/ 4::integer AS value_type, COALESCE(aigv.original_value_date,iv.value_date) as value_date, ind.indicator_id as me_indicator_id, t.amp_theme_id AS program_id, acv.id AS category_value_id, ind.output_id, ind.outcome_id FROM amp_indicator_connection con JOIN amp_indicator ind ON ind.indicator_id = con.indicator_id JOIN amp_indicator_disaggregation_values aidv ON ind.indicator_id = aidv.indicator_id JOIN amp_indicator_global_value aigv ON aidv.base_value_id = aigv.id JOIN amp_category_value acv ON acv.id = aidv.parent_category_id LEFT JOIN amp_theme t ON ind.program_id = t.amp_theme_id join amp_indicator_values iv ON con.id = iv.ind_connect_id WHERE con.activity_id IS NOT NULL
UNION ALL
/* indicator's values from admin section (disaggregated) - target values */ select DISTINCT con.activity_id as amp_activity_id, aigv.original_value AS value, /*aigv.type as value_type,*/ 5::integer AS value_type, COALESCE(aigv.original_value_date,iv.value_date) as value_date, ind.indicator_id as me_indicator_id, t.amp_theme_id AS program_id, acv.id AS category_value_id, ind.output_id, ind.outcome_id FROM amp_indicator_connection con JOIN amp_indicator ind ON ind.indicator_id = con.indicator_id JOIN amp_indicator_disaggregation_values aidv ON ind.indicator_id = aidv.indicator_id JOIN amp_indicator_global_value aigv ON aidv.target_value_id = aigv.id JOIN amp_category_value acv ON acv.id = aidv.parent_category_id LEFT JOIN amp_theme t ON ind.program_id = t.amp_theme_id join amp_indicator_values iv ON con.id = iv.ind_connect_id WHERE con.activity_id IS NOT NULL;
